import { useTranslation } from "react-i18next";
import { useMemo } from "react";
import { useSettingsContext } from "./SettingsContext";
import { SettingsSection } from "./SettingsSection";
import { Button, Icon, ListBox, ScrollArea } from "@cgs/ui";
import classNames from "classnames";
import { sendMessage } from "../common/messaging";

export const DisableBadgeForWebsitesSection = () => {
  const { t } = useTranslation(undefined, { keyPrefix: "settingsPage.DisableBadgeForWebsitesSection" });
  const { settings, saveSettings } = useSettingsContext();

  const options = useMemo(
    () =>
      settings.hiddenBadgeOrigins.map((hiddenBadgeOrigin) => ({
        id: hiddenBadgeOrigin,
      })),
    [settings.hiddenBadgeOrigins],
  );
  const handleWebsiteOptionSelect = async (activeOrigin: string) => {
    saveSettings(
      (prevSettings) => ({
        hiddenBadgeOrigins: prevSettings.hiddenBadgeOrigins.filter(
          (hiddenBadgeOrigin) => hiddenBadgeOrigin !== activeOrigin,
        ),
      }),
      async () => await sendMessage({ type: "updateContentScripts" }),
    );
    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Browser Extension Badge Unhidden",
        data: {
          origins: activeOrigin,
        },
      },
    });
  };

  const handleClearAll = async () => {
    saveSettings(
      {
        hiddenBadgeOrigins: [],
      },
      async () => await sendMessage({ type: "updateContentScripts" }),
    );
    await sendMessage({
      type: "logEvent",
      event: {
        name: "Citation Generator Browser Extension Badge Unhidden",
        data: {
          origins: "all",
        },
      },
    });
  };

  if (settings.hiddenBadgeOrigins.length === 0) {
    return (
      <SettingsSection title={t("title")} Icon={Icon.DisableSlash}>
        <p className="text-center">{t("noHiddenWebsites")}</p>
      </SettingsSection>
    );
  }

  return (
    <SettingsSection title={t("title")} Icon={Icon.DisableSlash}>
      <div className="-m-5">
        <ScrollArea>
          <div className="max-h-60">
            <ListBox.Root
              options={options}
              onOptionSelect={handleWebsiteOptionSelect}
              selectOptionOnMouseOver={false}
            >
              {settings.hiddenBadgeOrigins.map((hiddenBadgeOrigin) => (
                <ListBox.Option
                  className={classNames(
                    "group flex w-full cursor-pointer items-center justify-between overflow-hidden border-b border-b-navy-blue-6 px-5 py-3 outline-none hover:bg-navy-blue-3 aria-selected:bg-navy-blue-3",
                    "first-of-type:rounded-t-xl",
                  )}
                  id={hiddenBadgeOrigin}
                  key={hiddenBadgeOrigin}
                  aria-label={hiddenBadgeOrigin}
                >
                  <span>{hiddenBadgeOrigin}</span>
                  <span className="text-blue-9 opacity-0 transition-opacity group-hover:opacity-100 group-aria-selected:opacity-100">
                    {t("enableDomain")}
                  </span>
                </ListBox.Option>
              ))}
            </ListBox.Root>
          </div>
        </ScrollArea>
      </div>
      <div className="flex justify-end pt-5">
        <Button variant="outline" color="red" onClick={handleClearAll}>
          {t("clearAll")}
        </Button>
      </div>
    </SettingsSection>
  );
};
