import {
  forwardRef,
  ReactNode,
  RefObject,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { FixedSizeList } from "react-window";
import { filterItemData } from "./filter";
import { PortalContext, useIsomorphicLayoutEffect, useMatchSizes } from "../../";
import { Check } from "../Icon";
import * as Popover from "@radix-ui/react-popover";

export type SearchableSelectItemData = Array<Group>;
type Item = { value: string; label: string; onSelect?: () => void; icon?: SVGComponent };
type Group = { label?: string; items: Array<Item> };
type GroupLabel = string;

type FlattenedItemData = Array<Item | GroupLabel>;

const isGroupLabel = (item: Item | GroupLabel): item is GroupLabel => typeof item === "string";
const isItem = (item: Item | GroupLabel): item is Item => item.hasOwnProperty("value");

type RootProps = {
  value: string;
  onValueChange: (value: string) => void;
  children: ReactNode;
  emptyText: string;
  searchPlaceholder: string;
  itemData: SearchableSelectItemData;
  triggerRef?: RefObject<HTMLButtonElement>;
  portalContainer?: HTMLElement | null;
  contentAlign?: "start" | "end";
  contentSide?: "top" | "bottom";
  height?: number;
  itemSize?: number;
};

export function SearchableSelect({
  children,
  searchPlaceholder,
  emptyText,
  itemData,
  value,
  onValueChange,
  triggerRef,
  contentAlign = "start",
  height = 250,
  itemSize = 35,
  portalContainer,
  contentSide,
}: RootProps) {
  const { width } = useMatchSizes(triggerRef);
  const [inputValue, setInputValue] = useState("");
  const [open, setOpen] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const { portalRef } = useContext(PortalContext);

  const handleOpenChange = useCallback((open: boolean) => {
    if (!open) {
      setInputValue("");
    }
    setOpen(open);
  }, []);

  const handleValueChange = (newInputValue: typeof inputValue) => {
    handleOpenChange(false);
    onValueChange(newInputValue);
  };

  const handleInputValueChange = (inputValue: string) => {
    setInputValue(inputValue);
  };

  useEffect(() => {
    if (open && inputRef.current) {
      inputRef.current.focus();
    }
  }, [open]);

  return (
    <Popover.Root open={open} onOpenChange={handleOpenChange}>
      {/* disabling pointer events when open, fixes onOpenChange being called twice when closing in web component, possibly radix issue */}
      <Popover.Trigger asChild ref={triggerRef} className={open ? "pointer-events-none" : ""}>
        {children}
      </Popover.Trigger>
      <Popover.Portal container={portalRef?.current || portalContainer}>
        <Popover.Content
          className="navy-blue-11 overflow-hidden rounded-lg border border-navy-blue-7 bg-white text-sm shadow-md outline-none"
          sideOffset={8}
          align={contentAlign}
          side={contentSide}
          avoidCollisions={false}
          style={{ width: width ? `${width}px` : "20rem" }}
          ref={contentRef}
          onFocusOutside={() => console.log("onFocusOutside")}
        >
          <div className="p-2">
            <Input
              ref={inputRef}
              value={inputValue}
              onValueChange={handleInputValueChange}
              placeholder={searchPlaceholder}
            />
          </div>
          <hr />
          <div className="p-2">
            <List
              height={height}
              itemSize={itemSize}
              contentRef={contentRef}
              inputValue={inputValue}
              itemData={itemData}
              onValueChange={handleValueChange}
              emptyText={emptyText}
              value={value}
            />
          </div>
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}

type ListProps = {
  inputValue: string;
  itemData: SearchableSelectItemData;
  contentRef: RefObject<HTMLDivElement>;
  onValueChange: (value: string) => void;
  height: number;
  itemSize: number;
} & Pick<RootProps, "emptyText" | "value">;

const List = ({
  inputValue,
  itemData,
  contentRef,
  onValueChange,
  emptyText,
  value,
  height,
  itemSize,
}: ListProps) => {
  const [highlightedValue, setHighlightedValue] = useState<string | null>(value);
  const listRef: RefObject<FixedSizeList> = useRef(null);

  const filteredItemData = useMemo<FlattenedItemData>(() => {
    return filterItemData(itemData, inputValue).flatMap((group) => {
      if (group.label) {
        return [group.label, ...group.items];
      }
      return group.items;
    });
  }, [itemData, inputValue]);

  const scrollToItem = useCallback(
    (value: string) => {
      if (!listRef.current) {
        return;
      }
      const scrollToIndex = filteredItemData.findIndex(
        (filteredItem) => isItem(filteredItem) && filteredItem.value === value,
      );
      if (scrollToIndex === -1) {
        return;
      }
      listRef.current.scrollToItem(scrollToIndex, "smart");
    },
    [filteredItemData, listRef],
  );

  const highlightItem = useCallback(
    (value: string, scrollTo: boolean) => {
      setHighlightedValue(value);
      if (scrollTo) {
        scrollToItem(value);
      }
    },
    [scrollToItem],
  );

  const selectItem = useCallback(
    (value: string) => {
      onValueChange(value);
    },
    [onValueChange],
  );

  const highlightAdjacentItem = useCallback(
    (direction: "up" | "down") => {
      let adjacentItem: Item | undefined;
      let diff = direction === "up" ? -1 : 1;

      if (highlightedValue === null) {
        return;
      }

      const highlightedIndex = filteredItemData.findIndex(
        (item) => isItem(item) && item.value === highlightedValue,
      );

      while (adjacentItem === undefined) {
        const adjecantItemCandidate = filteredItemData[highlightedIndex + diff];

        if (adjecantItemCandidate === undefined) {
          break;
        }

        if (isItem(adjecantItemCandidate)) {
          highlightItem(adjecantItemCandidate.value, true);
          break;
        }

        // if we reached beginning or end of the list we need to scroll to separator
        const beforeOrAfterAdjacentCandidateIndex = highlightedIndex + diff * 2;
        const beforeOrAfterAdjacentCandidate = filteredItemData[beforeOrAfterAdjacentCandidateIndex];
        if (isGroupLabel(adjecantItemCandidate) && beforeOrAfterAdjacentCandidate === undefined) {
          listRef?.current?.scrollToItem(beforeOrAfterAdjacentCandidateIndex, "smart");
          break;
        }

        if (direction === "up") {
          diff--;
        } else {
          diff++;
        }
      }
    },
    [filteredItemData, highlightedValue, highlightItem],
  );

  useIsomorphicLayoutEffect(() => {
    scrollToItem(value);
  }, [value, scrollToItem]);

  // This will highlight the first item when user types something
  useEffect(() => {
    if (inputValue) {
      const firstItem = filteredItemData.find(isItem);
      if (firstItem) {
        highlightItem(firstItem.value, true);
      }
    }
  }, [inputValue, filteredItemData, highlightItem]);

  // This is used to update active item when user clicks arrow up/down
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      switch (event.key) {
        case "ArrowUp":
          highlightAdjacentItem("up");
          event.preventDefault();
          break;
        case "ArrowDown":
          highlightAdjacentItem("down");
          event.preventDefault();
          break;
        case "Enter":
          if (highlightedValue) {
            selectItem(highlightedValue);
          }
          event.preventDefault();
          break;
      }
    };

    const contentRefCurrent = contentRef.current;
    contentRefCurrent?.addEventListener("keydown", handleKeyDown);

    return () => contentRefCurrent?.removeEventListener("keydown", handleKeyDown);
  }, [contentRef, highlightedValue, selectItem, highlightAdjacentItem]);

  const EmptyState = () => <div className="py-9 text-center">{emptyText}</div>;

  if (filteredItemData.length === 0) {
    return <EmptyState />;
  }

  return (
    <FixedSizeList<FlattenedItemData>
      ref={listRef}
      height={Math.min(height, filteredItemData.length * itemSize)}
      itemCount={filteredItemData.length}
      itemSize={itemSize}
      width="100%"
      itemData={filteredItemData}
    >
      {({ style, data, index }) => {
        const Wrapper = ({ children }: { children: ReactNode }) => {
          return (
            <div
              style={{
                ...style,
                top: `${parseFloat(!style.top ? "0" : style.top.toString())}px`,
              }}
            >
              {children}
            </div>
          );
        };

        const item = data[index];
        if (item === undefined) {
          throw new Error("Item is undefined");
        }
        const nextItem = data[index + 1];

        if (!data.some(isItem)) {
          return (
            <Wrapper>
              <EmptyState />
            </Wrapper>
          );
        }

        if (isGroupLabel(item)) {
          if (!nextItem || isGroupLabel(nextItem)) {
            return null;
          }
          return (
            <Wrapper>
              <GroupLabel label={item} />
            </Wrapper>
          );
        }

        return (
          <Wrapper>
            <Item
              key={item.value}
              isHighlighted={highlightedValue === item.value}
              isSelected={value === item.value}
              onHighlight={() => highlightItem(item.value, false)}
              onSelect={item.onSelect || (() => selectItem(item.value))}
              item={item}
            />
          </Wrapper>
        );
      }}
    </FixedSizeList>
  );
};

type ItemProps = {
  item: Item;
  isHighlighted: boolean;
  isSelected: boolean;
  onHighlight: () => void;
  onSelect: () => void;
};

const Item = ({ item, isHighlighted, isSelected, onHighlight, onSelect }: ItemProps) => {
  return (
    <div
      className="border-t-1 flex cursor-pointer items-center space-x-2 rounded-md px-3 py-1.5 text-navy-blue-12 focus:outline-0 data-[highlighted=true]:bg-navy-blue-4"
      title={item.label}
      data-highlighted={isHighlighted}
      onClick={onSelect}
      onMouseMove={onHighlight}
      role="option"
    >
      {item.icon && <item.icon className="h-text shrink-0 fill-current" />}
      <div className="grow truncate">{item.label}</div>
      {isSelected && <Check className="h-text shrink-0 fill-current" />}
    </div>
  );
};

const GroupLabel = ({ label }: { label: ReactNode }) => {
  return <div className="px-3 py-1.5 text-xs font-bold text-navy-blue-12">{label}</div>;
};

type InputProps = {
  placeholder: string;
  value: string;
  onValueChange: (value: string) => void;
};

const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  { value, onValueChange, placeholder }: InputProps,
  ref,
) {
  return (
    <input
      ref={ref}
      value={value}
      onChange={(e) => onValueChange(e.target.value)}
      className="w-full rounded-md bg-navy-blue-4 px-2.5 py-1.5 outline-none placeholder:text-navy-blue-11"
      placeholder={placeholder}
    />
  );
});
