import { SearchableSelectItemData } from "./SearchableSelect";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const commandScore = require("command-score");

export function filterItemData(itemData: SearchableSelectItemData, search: string): SearchableSelectItemData {
  if (!search) {
    return itemData.filter((group) => group.items.length > 0);
  }

  const lowerSearch = search.toLowerCase();

  return itemData
    .map((group) => {
      const scoredItems = group.items
        .map((item) => {
          const lowerLabel = item.label.toLowerCase();
          const score = commandScore(lowerLabel, lowerSearch);
          return { score, ...item };
        })
        .filter(({ score }) => score > 0)
        .sort((a, b) => b.score - a.score)
        .map(({ score, ...rest }) => rest);
      return { ...group, items: scoredItems };
    })
    .filter((group) => group.items.length > 0);
}
