import { Button, Icon } from "@cgs/ui";
import { ScribbrEnv, UserInfo, UserLevel } from "@cgs/types";
import { useTranslation } from "react-i18next";
import { SettingsSection } from "./SettingsSection";
import { getHoustonHost } from "@cgs/utils";
import { DOMAIN } from "../common/constants";

export const AccountSettingsSection = ({ userInfo, env }: { userInfo: UserInfo; env: ScribbrEnv }) => {
  const { t } = useTranslation();

  return (
    <SettingsSection title={t("settingsPage.account")} Icon={Icon.User}>
      {userInfo.level === UserLevel.REGISTERED ? (
        <>
          <p>{t("settingsPage.loggedInAs", { email: userInfo.username })}</p>
          <div className="flex gap-5">
            <Button variant="outline" as="a" href={`${getHoustonHost(DOMAIN, env)}/account/manage-account/`}>
              {t("settingsPage.manageAccount")}
            </Button>
            <Button variant="outline" color="red" as="a" href={`${getHoustonHost(DOMAIN, env)}/logout`}>
              {t("settingsPage.logout")}
            </Button>
          </div>
        </>
      ) : (
        <>
          <p className="font-semibold">{t("settingsPage.loginWithScribbr")}</p>
          <div className="flex gap-5">
            <Button variant="solid" color="blue" as="a" href={`${getHoustonHost(DOMAIN, env)}/account/login/`}>
              {t("settingsPage.login")}
            </Button>
            <Button variant="outline" color="blue" as="a" href={`${getHoustonHost(DOMAIN, env)}/account/sign-up/`}>
              {t("settingsPage.signup")}
            </Button>
          </div>
        </>
      )}
    </SettingsSection>
  );
};
