/**
 * @todo When adding a new field, if this field is applicable to a source type that a PDF encompasses,
 *       make sure to add this field to the `PDF_SOURCE_SUBSET_JSON_SCHEMA` definition in the openai.ts file.
 */
export type Source = {
  id: ID;
  data: {
    type: SourceType;
    /** The language of the item */
    language?: string;
    /** The title or name of an item. */
    title?: string;
    /** The subtitle or name of an item. */
    subtitle?: string;
    /** The description of an item, mainly used when it has not title */
    description?: string;
    /** Name of the event (e.g. the conference name when citing a conference paper) */
    eventTitle?: string;
    /** Issue number of an item */
    issue?: string;
    /** Content of the item, mainly used for comments. Can be a snippet. */
    content?: string;
    /** Container section holding the item (e.g. “politics” for a newspaper article) */
    section?: string;
    // Date the item was retrieved
    accessed?: SourceDate;
    /** Date the item (e.g. a manuscript) has been submitted for publication */
    submitted?: SourceDate;
    /** The URL to the item */
    url?: string;
    /** Digital Object Identifier */
    doi?: string;
    /** Version of the item (e.g. “2.0.9” for a software program) */
    version?: string;
    /** Type or genre of the item (e.g. “adventure” for an adventure film, “PhD dissertation” for a PhD thesis) */
    genre?: string;
    /** Number identifying the item (e.g. a report number) */
    number?: string;
    /** Episode number for episodes of a podcast/TV show. */
    episode?: string;
    /** Season number for a season of a TV show, podcast, etc. */
    season?: string;
    /**
     * Way the content or information is communicated, shared, or published. For example,
     * E-book: PDF, JPEG file, Powerpoint, etc.
     * Painting/Artwork: Graphite on paper, Marble, Oil on canvas, etc.
     */
    medium?: string;
    /** Edition of the item */
    edition?: string;
    /** (publication) Status of the item (e.g. “in-press”) */
    status?: "published" | "in-press" | "unpublished";
    /** Volume number of the item */
    volume?: string | Range<string>;
    /** (range of) pages the item (e.g. a journal article) covers in a container (e.g. a journal issue) */
    page?: string | Range<string>;
    /** Date the item was issued/published */
    issued?: SourceDate;
    /** (issue) Date of the original version */
    originalDate?: SourceDate;
    /** The creators of a work */
    contributors?: SourceContributor[];
    /** Organization responsible for distributing the work. */
    publisher?: string;
    /** Issuing or judicial authority (e.g. “USPTO” for a patent, “Fairfax Circuit Court” for a legal case) */
    authority?: string;
    /** Date the source was completed, e.g. for artworks, sometimes also included for letters */
    composed?: SourceDate | Range<SourceDate>;
    /** Geographic scope of relevance (e.g. “US” for a US patent) */
    jurisdiction?: string;
    /** Geographic location of the publisher   */
    publisherPlace?: SourcePlace;
    /** Geographic location of the event related to the item */
    eventPlace?: SourcePlace;
    /** Archive storing the item */
    archive?: string;
    /** Geographic location of the archive  */
    archivePlace?: SourcePlace;
    /** Title of the container holding the item */
    containerTitle?: string;
    /** Title of the second container, or the source from whence the item originates */
    source?: string;
    /** Title of the collection holding the item (e.g. the series title for a book; the lecture series title for a presentation) */
    collectionTitle?: string;
    /** Descriptive text or notes about an item (e.g. in an annotated bibliography) */
    note?: string;
    image?: string;
    attribution?: {
      href: string;
      source: string;
    };
    pdfUrl?: string;
    comment?: string;
  };
  origin?: "openai";
  createdAt?: Date;
  updatedAt?: Date;
};

