export type DoiWorksRelation = "abstract" | "referenced" | "related" | "cited-by";

export type FeatureFlags = {
  autocitePdfEnabled: boolean;
};

export type AutociteRequest = (
  | {
      query: string;
      type: "query";
      requestedSourceType?: AutociteRequestedSourceType;
      orderBy?: AutociteOrderBy;
      language?: AutociteFilterLanguage;
      hasPdf?: boolean;
    }
  | {
      url: string;
      type: "url";
    }
  | {
      url: string;
      type: "youtube";
    }
  | {
      doi: string;
      type: "doi";
      relation?: DoiWorksRelation;
    }
  | {
      isbn: string;
      type: "isbn";
    }
  | {
      query: string;
      type: "query-book";
      orderBy?: AutociteOrderBy;
      language?: AutociteFilterLanguage;
    }
  | {
      query: string;
      type: "query-journal-article";
      orderBy?: AutociteOrderBy;
      language?: AutociteFilterLanguage;
      hasPdf?: boolean;
    }
  | {
      type: "html-document";
      url: string;
      html: string;
    }
  | {
      type: "abstract";
      doi: string;
    }
  | {
      type: "pdf";
      url: string;
      isUploaded: boolean;
      contents?: string;
    }
  | {
      type: "file-upload";
      s3Uri?: string;
    }
) & { featureFlags?: FeatureFlags };

