import { Checkbox, Icon } from "@cgs/ui";
import { Logo } from "../components/Logo";
import { useEffect } from "react";
import { ScribbrEnv } from "@cgs/types";
import { CitationStyleSelect } from "../components/CitationStyleSelect";
import { useTranslation } from "react-i18next";
import { useSettingsContext } from "./SettingsContext";
import { SettingsSection } from "./SettingsSection";
import { AccountSettingsSection } from "./AccountSettingsSection";
import { DisableBadgeForWebsitesSection } from "./DisableBadgeForWebsitesSection";
import { useSessionStorageContext } from "../components/SessionStorageProvider";
import { sendMessage } from "../common/messaging";
import { getScribbrHost } from "@cgs/utils";
import { DOMAIN } from "../common/constants";
import { GoogleDocsAccountSettings } from "./GoogleDocsAccountSettings";

export const SettingsPage = ({ env }: { env: ScribbrEnv }) => {
  const { t } = useTranslation();
  const { settings, saveSettings } = useSettingsContext();
  const { userInfo } = useSessionStorageContext();

  useEffect(() => {
    (async () => {
      await sendMessage({ type: "fetchUserInfo" });
    })();
  }, []);

  return (
    <div>
      <header className="flex border-b p-5">
        <a href={getScribbrHost(DOMAIN, env)} target="_blank" rel="noreferrer">
          <Logo className="h-6" />
        </a>
      </header>
      <div className="container mx-auto max-w-lg">
        <div className="space-y-9 py-9">
          <h1 className="heading-1 px-5">{t("settingsPage.title")}</h1>
          {userInfo && <AccountSettingsSection userInfo={userInfo} env={env} />}
          {settings.googleDocsToken && (
            <SettingsSection title={t("settingsPage.googleDocs.sectionHeader")} Icon={Icon.GoogleDocs}>
              <div className="flex flex-col gap-5">
                <GoogleDocsAccountSettings />
              </div>
            </SettingsSection>
          )}
          <SettingsSection title={t("settingsPage.general")} Icon={Icon.Gear}>
            <h3 className="w-full font-display font-bold">{t("settingsPage.citationStyle")}</h3>
            <CitationStyleSelect
              citationStyle={settings.citationStyle}
              onCitationStyleChange={(citationStyle) => saveSettings({ citationStyle })}
              shouldFitContainer
            />
          </SettingsSection>
          <SettingsSection title={t("settingsPage.citationBadge")} Icon={Icon.EyeSlash}>
            <div className="flex items-center space-x-3">
              <label className="flex items-center gap-3">
                <Checkbox
                  checked={settings.hideBadgeForAllOrigins !== true}
                  onCheckedChange={(e) => {
                    const hideBadge = e === "indeterminate" ? false : !e;
                    saveSettings(
                      { hideBadgeForAllOrigins: hideBadge },
                      async () => await sendMessage({ type: "updateContentScripts" }),
                    );
                    if (hideBadge) {
                      sendMessage({
                        type: "logEvent",
                        event: {
                          name: "Citation Generator Browser Extension Badge Hidden",
                          data: {
                            href: window.location.href,
                            hostname: window.location.hostname,
                            origins: "all",
                          },
                        },
                      });
                    } else {
                      sendMessage({
                        type: "logEvent",
                        event: {
                          name: "Citation Generator Browser Extension Badge Unhidden",
                          data: {
                            origins: "all",
                          },
                        },
                      });
                    }
                  }}
                />
                <div>{t("settingsPage.showBadge")}</div>
              </label>
            </div>
          </SettingsSection>
          <DisableBadgeForWebsitesSection />
        </div>
      </div>
    </div>
  );
};
