import { forwardRef, ReactNode, useRef } from "react";
import { useTranslation } from "react-i18next";
import { PromotedCitationStyles, CitationStyle, UnverifiedCitationStyles } from "@cgs/citation-engine/types";
import { getCitationStyleTranslation } from "../../common/utils";
import { Button, ButtonProps, SearchableSelect } from "@cgs/ui";
import { AngleDown } from "@cgs/ui/components/Icon";

export const CitationStyleSelect = forwardRef<
  HTMLButtonElement,
  {
    citationStyle: CitationStyle;
    onCitationStyleChange: (value: CitationStyle) => void;
    children?: ReactNode;
    citationStyles?: Array<CitationStyle>;
    contentMatchTriggerWidth?: boolean;
    contentAlign?: "start" | "end";
    contentSide?: "top" | "bottom";
  } & Pick<ButtonProps, "aria-label" | "id" | "color" | "size" | "variant" | "shouldFitContainer" | "startIcon">
>(function CitationStyleSelect(
  {
    citationStyle,
    onCitationStyleChange,
    citationStyles = PromotedCitationStyles,
    children,
    contentMatchTriggerWidth = false,
    "aria-label": ariaLabel,
    id,
    color,
    size,
    variant,
    shouldFitContainer,
    startIcon,
    contentAlign = "start",
    contentSide = "bottom",
  },
  ref,
) {
  const { t } = useTranslation();
  const triggerRef = useRef<HTMLButtonElement>(null);

  const handleValueChange = (value: string) => {
    const citationStyle = JSON.parse(value) as CitationStyle;
    onCitationStyleChange(citationStyle);
  };

  const itemsGroup = {
    items: citationStyles
      .map((citationStyle) => {
        return {
          label: getCitationStyleTranslation(citationStyle, t),
          value: JSON.stringify(citationStyle),
        };
      })
      .sort((a, b) => a.label.localeCompare(b.label)),
  };
  const unverifiedItemsGroup = {
    label: t("citationStyleSelect.unverifiedHeading"),
    items: UnverifiedCitationStyles.map((citationStyle) => ({
      label: getCitationStyleTranslation(citationStyle, t),
      value: JSON.stringify(citationStyle),
    })).sort((a, b) => a.label.localeCompare(b.label)),
  };

  const itemData = [itemsGroup, unverifiedItemsGroup];

  return (
    <SearchableSelect
      value={JSON.stringify(citationStyle)}
      onValueChange={handleValueChange}
      searchPlaceholder={t("citationStyleSelect.searchPlaceholder")}
      emptyText={t("citationStyleSelect.emptyText")}
      itemData={itemData}
      contentAlign={contentAlign}
      triggerRef={contentMatchTriggerWidth ? triggerRef : undefined}
      height={200}
      contentSide={contentSide}
    >
      <Button
        ref={ref}
        endIcon={AngleDown}
        justify="between"
        aria-label={ariaLabel}
        id={id}
        color={color}
        size={size}
        variant={variant}
        shouldFitContainer={shouldFitContainer}
        startIcon={startIcon}
      >
        {children || getCitationStyleTranslation(citationStyle, t)}
      </Button>
    </SearchableSelect>
  );
});
