import { UnverifiedCitationStyles } from "./unverified";

export const PromotedCitationStyles = [
  ["apa", "v6"],
  ["apa", "v7"],
  ["mla", "v8"],
  ["mla", "v9"],
  ["harvard-cite-them-right", "v12"],
  ["harvard-deakin-university", null],
  ["deutsche-zitierweise", null],
  ["harvard-zitierweise", null],
  ["chicago-fullnote-bibliography", "v17"],
  ["chicago-author-date", "v17"],
  ["ieee", null],
  ["ama", "v10"],
  ["ama", "v11"],
  ["acs", null],
  ["cse", null],
  ["cse-author-date", null],
  ["turabian-fullnote-bibliography", null],
  ["turabian-author-date", null],
  ["asa", "v6"],
  ["vancouver", null],
  ["vancouver-author-date", null],
] as const;

export type PromotedCitationStyle = (typeof PromotedCitationStyles)[number];
export type PromotedCitationStyleId = (typeof PromotedCitationStyles)[number][0];
export type PromotedCitationStyleVariation = (typeof PromotedCitationStyles)[number][1];

export type UnverifiedCitationStyle = (typeof UnverifiedCitationStyles)[number];

export type CitationStyle = PromotedCitationStyle | UnverifiedCitationStyle;

export * from "./unverified";

import type { Citation, Locale, Source } from "@cgs/types";
import type * as CiteProc from "citeproc";

export type EngineOptions = {
  annotated: boolean;
};

export type CitationStyleConfig = {
  getExamples: (
    sources: Array<CiteProc.Source>,
    citationItems: Array<CiteProc.CitationItem>,
    citationStyle: CitationStyle,
    locale: Locale,
    englineOptions?: EngineOptions,
  ) => Citation;
  mappers: Array<Mapper>;
  corrections: Array<Correction>;
};

export type Mapper = (
  acc: Partial<CiteProc.Source>,
  source: Source,
  locale: Locale,
  citationStyle: PromotedCitationStyle,
  inText?: boolean,
) => void;

export type Correction = (text: string, source?: Source) => string;
