import { ReactNode } from "react";
import * as RadixScrollArea from "@radix-ui/react-scroll-area";
import classNames from "classnames";

type ScrollAreaProps = {
  children: ReactNode;
  orientation?: "vertical" | "horizontal";
};

export function ScrollArea({ children, orientation = "vertical" }: ScrollAreaProps) {
  return (
    <RadixScrollArea.Root className="h-full">
      {/* Last `[&>:first-of-type]:!block` class is a temporary fix for a bug in Radix ScrollArea
       * https://github.com/radix-ui/primitives/issues/926
       */}
      <RadixScrollArea.Viewport className="h-full w-full [&>:first-of-type]:!block">
        {children}
      </RadixScrollArea.Viewport>
      <RadixScrollArea.Scrollbar
        className={classNames("flex touch-none select-none p-0.5 transition-all duration-150 ease-out", {
          "w-2.5": orientation === "vertical",
          "h-2.5": orientation === "horizontal",
        })}
        orientation={orientation}
      >
        <RadixScrollArea.Thumb
          className={classNames(
            "relative rounded-full bg-navy-blue-7 before:absolute before:left-2/4 before:top-2/4 before:h-full before:min-h-11 before:w-full before:min-w-11 before:-translate-x-1/2 before:-translate-y-1/2 before:content-['']",
            { "flex-1": orientation === "vertical" },
          )}
        />
      </RadixScrollArea.Scrollbar>
    </RadixScrollArea.Root>
  );
}
